1	// ivdr-wiki/src/components/ISO13485Map.tsx
2	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
3	import { Link, useNavigate, useParams } from "react-router-dom";
4	import { CheckCircle, FolderTree, Library } from "lucide-react";
5	import {
6	  iso13485Phases,
7	  iso13485Stations,
8	  type ISO13485PhaseId,
9	} from "../data/iso13485/stations";
10	import { PhaseBand } from "./PhaseBand";
11	import { PhaseNav } from "./PhaseNav";
12	import { StationDetail } from "./StationDetail";
13	import type { Phase, Station, PhaseId } from "../data/stations";
14	
15	function adaptPhase(p: typeof iso13485Phases[0]): Phase {
16	  return { ...p, id: p.id as unknown as PhaseId };
17	}
18	
19	function adaptStation(s: typeof iso13485Stations[0]): Station {
20	  return { ...s, phase: s.phase as unknown as PhaseId };
21	}
22	
23	export function ISO13485Map() {
24	  const navigate = useNavigate();
25	  const { id } = useParams();
26	
27	  const adaptedPhases = useMemo(() => iso13485Phases.map(adaptPhase), []);
28	  const adaptedStations = useMemo(() => iso13485Stations.map(adaptStation), []);
29	
30	  const stationsByPhase = useMemo(() => {
31	    const map = {} as Record<string, Station[]>;
32	    for (const p of adaptedPhases) {
33	      map[p.id] = adaptedStations.filter((s) => s.phase === p.id);
34	    }
35	    return map;
36	  }, [adaptedPhases, adaptedStations]);
37	
38	  const openId = id ? Number(id) : null;
39	  const activeStation =
40	    openId != null
41	      ? adaptedStations.find((s) => s.id === openId) ?? null
42	      : null;
43	
44	  const openStation = useCallback(
45	    (sid: number) => navigate(`/iso13485/station/${sid}`),
46	    [navigate],
47	  );
48	  const closeStation = useCallback(() => navigate("/iso13485"), [navigate]);
49	
50	  const [activePhase, setActivePhase] = useState<ISO13485PhaseId | null>("qms");
51	  const bandRefs = useRef<Map<string, HTMLElement>>(new Map());
52	
53	  useEffect(() => {
54	    const observer = new IntersectionObserver(
55	      (entries) => {
56	        const visible = entries
57	          .filter((e) => e.isIntersecting)
58	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
59	        if (visible) {
60	          const pid = (visible.target as HTMLElement).dataset
61	            .phase as ISO13485PhaseId;
62	          if (pid) setActivePhase(pid);
63	        }
64	      },
65	      { rootMargin: "-45% 0px -45% 0px", threshold: [0, 0.25, 0.5, 1] },
66	    );
67	    bandRefs.current.forEach((el) => observer.observe(el));
68	    return () => observer.disconnect();
69	  }, []);
70	
71	  return (
72	    <div className="min-h-screen bg-bg">
73	      <PhaseNav
74	        activePhase={activePhase as unknown as PhaseId}
75	        overridePhases={adaptedPhases}
76	      />
77	
78	      <main
79	        className="mx-auto"
80	        style={{
81	          maxWidth: "var(--max-w)",
82	          padding: "var(--s-12) var(--margin) var(--s-16)",
83	        }}
84	      >
85	        {/* Hero */}
86	        <header style={{ marginBottom: "var(--s-12)" }}>
87	          <span
88	            className="inline-flex items-center gap-2 rounded-full font-semibold"
89	            style={{
90	              background: "var(--p3-tint)",
91	              color: "var(--p3)",
92	              fontSize: "var(--t-sm)",
93	              padding: "4px 12px",
94	            }}
95	          >
96	            <CheckCircle size={16} strokeWidth={2.5} aria-hidden />
97	            ISO 13485 인증 여정 · 4 페이즈 10 정거장
98	          </span>
99	          <h1
100	            className="font-extrabold text-text"
101	            style={{
102	              fontSize: "var(--t-3xl)",
103	              lineHeight: "var(--lh-tight)",
104	              marginTop: "var(--s-4)",
105	              maxWidth: 760,
106	            }}
107	          >
108	            <span style={{ color: "var(--p3)" }}>
109	              QMS 수립 · 심사 준비 · 지속 개선
110	            </span>
111	          </h1>
112	          <p
113	            className="text-text-muted"
114	            style={{
115	              fontSize: "var(--t-lg)",
116	              marginTop: "var(--s-4)",
117	              maxWidth: 640,
118	            }}
119	          >
120	            Clause 4–8을 4개 페이즈로 구분했다. 카드를 누르면 본문·지금 할
121	            일·관련 조항이 열린다.
122	          </p>
123	
124	          <div className="flex flex-wrap gap-3" style={{ marginTop: "var(--s-6)" }}>
125	            <Link
126	              to="/documents"
127	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] font-bold text-text-on-color"
128	              style={{
129	                background: "var(--p3)",
130	                fontSize: "var(--t-sm)",
131	                padding: "11px 18px",
132	                minHeight: 44,
133	              }}
134	            >
135	              <FolderTree size={18} aria-hidden />
136	              공통 문서 전체 보기
137	            </Link>
138	            <Link
139	              to="/wiki"
140	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text hover:bg-surface"
141	              style={{
142	                borderColor: "var(--border-strong)",
143	                fontSize: "var(--t-sm)",
144	                padding: "11px 18px",
145	                minHeight: 44,
146	              }}
147	            >
148	              <Library size={18} style={{ color: "var(--info)" }} aria-hidden />
149	              개념 위키
150	            </Link>
151	            <Link
152	              to="/"
153	              className="inline-flex items-center gap-2 rounded-[var(--r-md)] border font-bold text-text-muted hover:bg-surface"
154	              style={{
155	                borderColor: "var(--border)",
156	                fontSize: "var(--t-sm)",
157	                padding: "11px 18px",
158	                minHeight: 44,
159	              }}
160	            >
161	              ← 인증 허브
162	            </Link>
163	          </div>
164	        </header>
165	
166	        {/* 4 페이즈 밴드 */}
167	        <div className="flex flex-col" style={{ gap: "var(--s-8)" }}>
168	          {adaptedPhases.map((p) => (
169	            <PhaseBand
170	              key={p.id}
171	              phase={p}
172	              stations={stationsByPhase[p.id] ?? []}
173	              activeId={openId ?? undefined}
174	              onOpen={openStation}
175	              registerRef={(el) => {
176	                if (el) {
177	                  el.dataset.phase = p.id;
178	                  bandRefs.current.set(p.id, el);
179	                } else {
180	                  bandRefs.current.delete(p.id);
181	                }
182	              }}
183	            />
184	          ))}
185	        </div>
186	
187	        <footer
188	          className="text-text-subtle"
189	          style={{
190	            fontSize: "var(--t-xs)",
191	            marginTop: "var(--s-12)",
192	            lineHeight: "var(--lh-base)",
193	          }}
194	        >
195	          ISO 13485:2016 내용은 2026년 6월 기준 확인값입니다. 실제 인증 진행 시
196	          최신 표준 원문·인증기관 요건으로 재확인하세요.
197	        </footer>
198	      </main>
199	
200	      <StationDetail station={activeStation} onClose={closeStation} certId="iso13485" />
201	    </div>
202	  );
203	}
204

