// ivdr-wiki/src/data/mdsap/stations.ts

export type MDSAPPhaseId = "mdsap-prep" | "mdsap-qms" | "mdsap-audit" | "mdsap-maintain";

export interface MDSAPPhase {
  id: MDSAPPhaseId;
  order: number;
  title: string;
  subtitle: string;
  colorVar: string;
  tintVar: string;
}

export interface MDSAPStation {
  id: number;
  phase: MDSAPPhaseId;
  title: string;
  icon: string;
  oneLine: string;
  tag: { label: string; tone: "neutral" | "info" | "warning" | "danger" | "success" };
  body: string[];
  todo: string;
  refs: string[];
  note?: string;
}

export const mdsapPhases: MDSAPPhase[] = [
  { id: "mdsap-prep",     order: 1, title: "사전 준비",  subtitle: "Gap 분석 및 추진 계획 수립",        colorVar: "--p1", tintVar: "--p1-tint" },
  { id: "mdsap-qms",      order: 2, title: "QMS 구축",   subtitle: "7개 챕터별 절차서 정비",            colorVar: "--p2", tintVar: "--p2-tint" },
  { id: "mdsap-audit",    order: 3, title: "심사 대비",  subtitle: "내부심사·본심사·불일치 처리",       colorVar: "--p3", tintVar: "--p3-tint" },
  { id: "mdsap-maintain", order: 4, title: "사후 관리",  subtitle: "지속 개선 및 재인증",               colorVar: "--p4", tintVar: "--p4-tint" },
];

export const mdsapPhaseById = (id: MDSAPPhaseId): MDSAPPhase =>
  mdsapPhases.find((p) => p.id === id)!;

export const mdsapStationsByPhase = (): Record<MDSAPPhaseId, MDSAPStation[]> => {
  const map = {} as Record<MDSAPPhaseId, MDSAPStation[]>;
  for (const p of mdsapPhases) {
    map[p.id] = mdsapStations.filter((s) => s.phase === p.id);
  }
  return map;
};

export const mdsapStations: MDSAPStation[] = [
  {
    id: 1,
    phase: "mdsap-prep",
    title: "Gap 분석 & 추진 계획",
    icon: "search",
    oneLine: "ISO 13485 현행 QMS vs MDSAP 7챕터 요건 비교 및 개선 우선순위 결정",
    tag: { label: "현황 진단", tone: "info" },
    body: [
      "MDSAP(Medical Device Single Audit Program)는 FDA(미국), Health Canada(캐나다), ANVISA(브라질), TGA(호주), MHLW/PMDA(일본) 5개 규제기관이 공동으로 인정하는 단일 심사 프로그램이다. ISO 13485:2016을 기반으로 하되 각국 규제 요건을 추가로 포함한다.",
      "Gap 분석은 현행 QMS가 MDSAP 7개 챕터(경영·시장허가·측정개선·설계개발·생산서비스·구매·고객중심 프로세스)와 어떻게 다른지 파악하는 첫 단계다. 특히 FDA 21 CFR Part 820, Health Canada CMDR, TGA MDR 등 국가별 추가 요건을 반드시 포함해야 한다.",
    ],
    todo: "MDSAP Audit Approach 기준으로 챕터별 Gap 분석 보고서 작성",
    refs: ["MDSAP Audit Approach Document", "ISO 13485:2016", "FDA 21 CFR Part 820"],
  },
  {
    id: 2,
    phase: "mdsap-qms",
    title: "Chapter 1-2: 경영 & 등록",
    icon: "briefcase",
    oneLine: "경영 책임(Ch.1)과 시장 허가·시설 등록(Ch.2) 절차서 구축",
    tag: { label: "경영·등록", tone: "info" },
    body: [
      "**Chapter 1(Management)**: 최고경영진의 QMS 책임, 범위 설정, 관리 검토, PRRC(규제 요건 책임자) 역할 포함. 경영 검토는 MDSAP 8개 필수 입력 항목(고객 피드백·내부심사·규제 요건 변경 등)을 모두 포함해야 한다.",
      "**Chapter 2(Device Marketing Authorization and Facility Registration)**: 각 대상 국가(미국·캐나다·브라질·호주·일본)의 시장 허가 및 시설 등록 상태를 문서화하고, 변경 통보 절차를 SOP에 반영해야 한다.",
    ],
    todo: "경영 책임 절차서 + 시장 허가·시설 등록 현황표 작성",
    refs: ["MDSAP Ch.1", "MDSAP Ch.2", "FDA 21 CFR 807", "Health Canada CMDR S.44"],
  },
  {
    id: 3,
    phase: "mdsap-qms",
    title: "Chapter 3-4: 측정·개선 & 설계",
    icon: "pen-tool",
    oneLine: "측정·분석·개선(Ch.3)과 설계·개발 관리(Ch.4) 절차서 정비",
    tag: { label: "측정·설계", tone: "info" },
    body: [
      "**Chapter 3(Measurement, Analysis and Improvement)**: 고객 불만·내부심사·제품 모니터링·바이질런스·CAPA 프로세스. FDA 21 CFR Part 820 Subpart M(기록)과 N(서비스)을 포함한다.",
      "**Chapter 4(Design and Development)**: 설계 계획→입력→출력→검토→검증→유효성확인→이전→변경관리 전 과정. 설계 이력 파일(DHF)은 MDSAP 심사의 핵심 증거다. 캐나다는 Part C, Div.1의 추가 설계 요건에 주의한다.",
    ],
    todo: "측정·개선 절차서(CAPA 포함) + 설계 관리 절차서(DHF 구조 포함) 작성",
    refs: ["MDSAP Ch.3", "MDSAP Ch.4", "ISO 13485:2016 §8", "§7.3"],
  },
  {
    id: 4,
    phase: "mdsap-qms",
    title: "Chapter 5-6: 생산·구매",
    icon: "factory",
    oneLine: "생산·서비스 통제(Ch.5)와 구매·공급자 관리(Ch.6) 절차서 정비",
    tag: { label: "생산·구매", tone: "info" },
    body: [
      "**Chapter 5(Production and Service Controls)**: 생산 공정 통제, 배치 기록, 추적성, 멸균(해당 시), 측정장비 교정, 제품 출하 통제. FDA 21 CFR 820.60~820.80 요건이 추가로 적용된다.",
      "**Chapter 6(Purchasing)**: 공급자 선정·평가·재평가, 승인공급자목록(ASL), 구매 정보·검사. 브라질 ANVISA는 공급자 심사 기록을 포르투갈어로 유지해야 한다는 추가 요건이 있다.",
    ],
    todo: "생산 통제 절차서(배치 기록 포함) + 구매·공급자 관리 절차서(ASL 포함) 작성",
    refs: ["MDSAP Ch.5", "MDSAP Ch.6", "FDA 21 CFR 820.60", "820.80"],
  },
  {
    id: 5,
    phase: "mdsap-audit",
    title: "내부 심사 & 경영 검토",
    icon: "clipboard-check",
    oneLine: "MDSAP 7챕터 기반 내부 심사 + 경영 검토로 본 심사 준비 완성",
    tag: { label: "심사 준비", tone: "warning" },
    body: [
      "MDSAP 내부 심사는 ISO 13485 내부 심사와 달리 7개 챕터를 모두 커버해야 한다. 부적합은 등급(Minor/Major/Critical)을 부여하고 CAPA와 연결해야 한다.",
      "경영 검토는 MDSAP Ch.1 필수 입력 8개 항목을 모두 다루어야 한다. 심사관(AO)은 경영 검토 기록이 형식적이지 않고 실질적 개선 결정으로 이어지는지 확인한다.",
    ],
    todo: "MDSAP 7챕터 기반 내부 심사 계획·수행·보고서 작성 + 경영 검토 기록 작성",
    refs: ["MDSAP Ch.1", "MDSAP Audit Approach §3.4", "ISO 13485:2016 §5.6", "§8.2.2"],
    note: "본 심사 최소 6개월 전 내부 심사 완료 권장",
  },
  {
    id: 6,
    phase: "mdsap-audit",
    title: "MDSAP 본 심사",
    icon: "user-check",
    oneLine: "감사 조직(AO) 선정 → 초기 심사 실시 → 불일치 처리",
    tag: { label: "본 심사", tone: "danger" },
    body: [
      "MDSAP 본 심사는 MDSAP 승인 감사 조직(Auditing Organization, AO)이 수행한다. AO는 MDSAP 웹사이트에서 인정 기관별 목록을 확인할 수 있다. 초기 심사는 Stage 1(문서 검토)과 Stage 2(현장 심사)로 구성된다.",
      "심사 결과 부적합(Nonconformity)이 발생하면: **Minor** → 90일 내 CAPA 계획 제출; **Major** → 30일 내 CAPA 계획, 180일 내 효과 검증; **Critical** → 즉시 5개 규제기관에 통보. 부적합 처리가 불충분하면 인증이 취소될 수 있다.",
    ],
    todo: "AO 선정·계약 → Stage 1/2 심사 일정 수립 → 불일치 대응 절차 수립",
    refs: ["MDSAP Audit Approach", "MDSAP NC Grading Guidance", "MDSAP AO List"],
  },
  {
    id: 7,
    phase: "mdsap-maintain",
    title: "인증 유지 & 지속 개선",
    icon: "trending-up",
    oneLine: "연간 감시 심사(Surveillance) + 3년 재인증 + CAPA 루프 유지",
    tag: { label: "지속 개선", tone: "success" },
    body: [
      "MDSAP 인증은 3년 주기이며, 매년 감시 심사(Surveillance Audit)가 수행된다. 감시 심사는 전체 7챕터 중 일부를 순환하며 심사한다.",
      "연간 감시 심사 전까지 미결 CAPA를 모두 종결하고, 경영 검토를 최소 1회 실시해야 한다. 규제 요건 변경(예: FDA CFR 개정, Health Canada CMDR 개정) 모니터링도 Chapter 1 의무 사항이다.",
    ],
    todo: "연간 내부 심사 계획 + CAPA 현황 모니터링 + 규제 변경 추적 체계 수립",
    refs: ["MDSAP Audit Approach §3.5", "MDSAP Surveillance Guidance"],
