// ivdr-wiki/src/components/MDSAPMap.tsx
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import {
  mdsapPhases,
  mdsapStations,
  type MDSAPPhaseId,
} from "../data/mdsap/stations";
import { PhaseBand } from "./PhaseBand";
import { PhaseNav } from "./PhaseNav";
import { StationDetail } from "./StationDetail";
import type { Phase, Station, PhaseId } from "../data/stations";

function adaptPhase(p: typeof mdsapPhases[0]): Phase {
  return { ...p, id: p.id as unknown as PhaseId };
}

function adaptStation(s: typeof mdsapStations[0]): Station {
  return { ...s, phase: s.phase as unknown as PhaseId };
}

export function MDSAPMap() {
  const navigate = useNavigate();
  const { id } = useParams();

  const adaptedPhases = useMemo(() => mdsapPhases.map(adaptPhase), []);
  const adaptedStations = useMemo(() => mdsapStations.map(adaptStation), []);

  const stationsByPhase = useMemo(() => {
    const map = {} as Record<string, Station[]>;
    for (const p of adaptedPhases) {
      map[p.id] = adaptedStations.filter((s) => s.phase === p.id);
    }
    return map;
  }, [adaptedPhases, adaptedStations]);

  const openId = id ? Number(id) : null;
  const activeStation =
    openId != null
      ? adaptedStations.find((s) => s.id === openId) ?? null
      : null;

  const openStation = useCallback(
    (sid: number) => navigate(`/mdsap/station/${sid}`),
    [navigate],
  );
  const closeStation = useCallback(() => navigate("/mdsap"), [navigate]);

  const [activePhase, setActivePhase] = useState<MDSAPPhaseId | null>("mdsap-prep");
  const bandRefs = useRef<Map<string, HTMLElement>>(new Map());

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
        if (visible) {
          const pid = (visible.target as HTMLElement).dataset
            .phase as MDSAPPhaseId;
          if (pid) setActivePhase(pid);
        }
      },
      { rootMargin: "-45% 0px -45% 0px", threshold: [0, 0.25, 0.5, 1] },
    );
    bandRefs.current.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);

  return (
    <div className="min-h-screen bg-bg">
      <PhaseNav
        activePhase={activePhase as unknown as PhaseId}
        overridePhases={adaptedPhases}
      />

      <main
        className="mx-auto"
        style={{
          maxWidth: "var(--max-w)",
          padding: "var(--s-12) var(--margin) var(--s-16)",
        }}
      >
        {/* Hero */}
        <header style={{ textAlign: "center", marginBottom: "var(--s-10)", paddingTop: "var(--s-6)" }}>
          <span
            style={{
              fontSize: "var(--t-xs)",
              background: "var(--p4-tint)",
              color: "var(--p4)",
              borderRadius: "var(--r-full)",
              padding: "4px 14px",
              fontWeight: 700,
            }}
          >
            Medical Device Single Audit Program
          </span>
          <h1
            style={{
              fontSize: "var(--t-3xl)",
              fontWeight: 900,
              color: "var(--text)",
              marginTop: "var(--s-3)",
            }}
          >
            MDSAP 여정
          </h1>
          <p
            style={{
              fontSize: "var(--t-base)",
              color: "var(--text-muted)",
              marginTop: "var(--s-2)",
            }}
          >
            FDA · Health Canada · ANVISA · TGA · PMDA/MHLW 5개국 단일 심사 · 4단계 · 7 정거장 · 10개 문서
          </p>
        </header>

        {/* Countries banner */}
        <div
          className="flex flex-wrap items-center gap-2 justify-center"
          style={{ marginBottom: "var(--s-8)" }}
        >
          {[
            "🇺🇸 FDA (미국)",
            "🇨🇦 Health Canada",
            "🇧🇷 ANVISA (브라질)",
            "🇦🇺 TGA (호주)",
            "🇯🇵 PMDA (일본)",
          ].map((c) => (
            <span
              key={c}
              className="rounded-full font-semibold"
              style={{
                background: "var(--p4-tint)",
                color: "var(--p4)",
                fontSize: "var(--t-xs)",
                padding: "4px 12px",
                border: "1px solid var(--p4)",
              }}
            >
              {c}
            </span>
          ))}
        </div>

        {/* 4 페이즈 밴드 */}
        <div className="flex flex-col" style={{ gap: "var(--s-8)" }}>
          {adaptedPhases.map((p) => (
            <PhaseBand
              key={p.id}
              phase={p}
              stations={stationsByPhase[p.id] ?? []}
              activeId={openId ?? undefined}
              onOpen={openStation}
              registerRef={(el) => {
                if (el) {
                  el.dataset.phase = p.id;
                  bandRefs.current.set(p.id, el);
                } else {
                  bandRefs.current.delete(p.id);
                }
              }}
            />
          ))}
        </div>

        <footer
          className="text-text-subtle"
          style={{
            fontSize: "var(--t-xs)",
            marginTop: "var(--s-12)",
            lineHeight: "var(--lh-base)",
          }}
        >
          MDSAP 내용은 2026년 6월 기준 확인값입니다. 실제 인증 진행 시
          최신 MDSAP Audit Approach 문서·AO 요건으로 재확인하세요.
        </footer>
      </main>

      <StationDetail station={activeStation} onClose={closeStation} certId="mdsap" />
    </div>
  );
}

